// Declarative service runner. No eval, imported code or implicit ECU addresses.
import {normalizedHex as hex,canAddress} from './scan.js';
const readHex=h=>/^(?:21[0-9A-F]{2}|22[0-9A-F]{4})$/.test(hex(h));
const check=(c,ecu)=>{const r=ecu.reads().find(r=>r.name===c.request);if(!r||!readHex(r.sentbytes)||!(c.item in (r.receivebyte_dataitems||{})))throw Error('Kontrola neodkazuje na přesný čtecí parametr DDT.');if(!['eq','ne','gte','lte','between'].includes(c.op))throw Error('Neplatná podmínka.');if(!Number.isFinite(c.value)||(c.op==='between'&&(!Number.isFinite(c.max)||c.max<c.value)))throw Error('Podmínka musí mít číselné meze.');return r;};
export function validateScenario(source,ecu){
 const s=JSON.parse(JSON.stringify(source));if(s.schema!=='espaceweb.service.v1'||!s.id||!s.title||!Array.isArray(s.instructions)||!s.instructions.length)throw Error('Neplatný scénář nebo chybí pokyny.');
 if(s.demoOnly!==true){if(!s.reference||!Array.isArray(s.fingerprint)||s.fingerprint.length<2)throw Error('Scénář potřebuje zdroj dokumentace a nejméně dva přesné identifikační otisky.');}
 if(!s.target||s.target.name!==ecu.name||hex(s.target.tx)+':'+hex(s.target.rx)!==canAddress(ecu))throw Error('Scénář neodpovídá názvu a adresám aktivní CAN ECU.');
 if(!Array.isArray(s.fingerprint))s.fingerprint=[];if(new Set(s.fingerprint.map(f=>hex(f.request))).size!==s.fingerprint.length)throw Error('Identifikační otisky nesmí opakovat stejný požadavek.');for(const f of s.fingerprint){if(!readHex(f.request)||!/^([0-9A-F]{2})+$/.test(hex(f.response))||!hex(f.response).startsWith((parseInt(hex(f.request).slice(0,2),16)+64).toString(16).toUpperCase()+hex(f.request).slice(2)))throw Error('Neplatný identifikační otisk.');}
 if(s.session&&!['1001','1003','10C0'].includes(hex(s.session)))throw Error('Nepodporovaná diagnostická relace.');
 if(!Array.isArray(s.preconditions)||!s.preconditions.length)throw Error('Chybí vstupní podmínky.');for(const c of s.preconditions)check(c,ecu);
 if(!Array.isArray(s.steps)||!s.steps.length||s.steps.length>64)throw Error('Scénář vyžaduje 1–64 kroků.');
 let started=false;for(const step of s.steps){if(step.type==='read'){const r=ecu.reads().find(r=>r.name===step.request);if(!r||!readHex(r.sentbytes))throw Error('Neplatný čtecí krok.');}
 else if(step.type==='routine'){const r=ecu.requests.find(r=>r.name===step.request);if(!r||!/^310[123][0-9A-F]{4}(?:[0-9A-F]{2}){0,3}$/.test(hex(r.sentbytes))||Object.keys(r.sendbyte_dataitems||{}).length)throw Error('Rutina vyžaduje pevný UDS 31 požadavek bez dynamických polí, nejvýše 7 bajtů.');if(!/^([0-9A-F]{2})+$/.test(hex(step.expect))||!hex(step.expect).startsWith('71'+hex(r.sentbytes).slice(2,8)))throw Error('Rutina potřebuje úplnou očekávanou odpověď 71 se správným ID.');if(hex(r.sentbytes).startsWith('3101'))started=true;}
 else if(step.type==='monitor'){check(step.until,ecu);if(!Number.isInteger(step.intervalMs)||step.intervalMs<500||step.intervalMs>5000||!Number.isInteger(step.timeoutMs)||step.timeoutMs<step.intervalMs||step.timeoutMs>900000)throw Error('Neplatný čas sledování.');}
 else throw Error('Nepodporovaný typ kroku.');}
 if(started){if(!s.stop)throw Error('Start rutiny vyžaduje definovaný příkaz zastavení.');const r=ecu.requests.find(r=>r.name===s.stop.request),starts=s.steps.filter(x=>x.type==='routine').map(x=>hex(ecu.requests.find(r=>r.name===x.request).sentbytes)).filter(x=>x.startsWith('3101'));
 if(!r||!/^3102[0-9A-F]{4}$/.test(hex(r.sentbytes))||Object.keys(r.sendbyte_dataitems||{}).length||starts.some(h=>h.slice(4,8)!==hex(r.sentbytes).slice(4,8))||!/^7102[0-9A-F]{4}(?:[0-9A-F]{2})*$/.test(hex(s.stop.expect))||!hex(s.stop.expect).startsWith('71'+hex(r.sentbytes).slice(2)))throw Error('Zastavení musí odpovídat ID startované rutiny.');}
 if(!Array.isArray(s.postconditions)||!s.postconditions.length)throw Error('Chybí ověření výsledku.');for(const c of s.postconditions)check(c,ecu);return s;
}
export function conditionPass(value,c){if(!Number.isFinite(value))return false;return ({eq:()=>value===c.value,ne:()=>value!==c.value,gte:()=>value>=c.value,lte:()=>value<=c.value,between:()=>value>=c.value&&value<=c.max})[c.op]();}
export class ScenarioRunner{
 constructor({ecu,request,signal,onEvent=()=>{},sleep=ms=>new Promise(r=>setTimeout(r,ms)),now=()=>Date.now(),persist=()=>{}}){Object.assign(this,{ecu,request,signal,onEvent,sleep,now,persist});this.events=[];this.started=false;}
 event(type,details){const e={time:new Date().toISOString(),type,...details};this.events.push(e);if(this.events.length>2000)this.events.shift();try{this.persist(this.events);}catch(error){this.storageError=error.message;}this.onEvent(e);}
 abort(){if(this.signal?.aborted)throw Error('Postup zrušen uživatelem.');}
 async send(command){const q=hex(command),r=hex(await this.request(q));if(!/^(?:[0-9A-F]{2})+$/.test(r)||r.startsWith('7F'))throw Error('Záporná nebo neplatná odpověď: '+r);this.event('response',{request:q,response:r});return r;}
 async fingerprint(s){for(const f of s.fingerprint){this.abort();if(await this.send(f.request)!==hex(f.response))throw Error('Neshoduje se identifikace ECU / verze SW.');}}
 async evaluate(c){const req=this.ecu.reads().find(r=>r.name===c.request),response=await this.send(req.sentbytes),q=hex(req.sentbytes);if(!response.startsWith((parseInt(q.slice(0,2),16)+64).toString(16).toUpperCase()+q.slice(2)))throw Error('Odpověď neodpovídá čtecímu požadavku.');const item=this.ecu.decode(req,response).find(x=>x.name===c.item);if(!item)throw Error('Parametr není v odpovědi.');const def=this.ecu.itemDef(c.item);let value=item.raw;if(def.scaled||def.step!=null||def.offset!=null||def.divideby)value=(item.raw*(def.step??1)+(def.offset??0))/(def.divideby||1);if(!Number.isFinite(value))throw Error('Parametr není číselný.');const passed=conditionPass(value,c);this.event('condition',{label:c.label||c.item,value,passed});return passed;}
 async checks(list){for(const c of list){this.abort();if(!await this.evaluate(c))throw Error('Nesplněná podmínka: '+(c.label||c.item));}}
 async keepAlive(s){if(!s.session)return;const r=await this.send('3E00');if(!r.startsWith('7E00'))throw Error('ECU nepotvrdila udržení diagnostické relace.');}
 async run(source,{demo=false}={}){const s=validateScenario(source,this.ecu);if(s.demoOnly&&!demo)throw Error('Ukázkový scénář nesmí komunikovat se skutečným vozidlem.');let completed=false,uncertain=false;
 this.event('begin',{scenario:s.id,demo});try{this.abort();await this.fingerprint(s);if(s.session){const r=await this.send(s.session);if(!r.startsWith('50'+hex(s.session).slice(2)))throw Error('ECU nepotvrdila relaci.');}await this.checks(s.preconditions);
 for(let i=0;i<s.steps.length;i++){this.abort();const step=s.steps[i];this.event('step',{index:i,title:step.title||step.request||'Sledování'});
 if(step.type==='read'){const r=this.ecu.reads().find(r=>r.name===step.request),q=hex(r.sentbytes),reply=await this.send(q);if(!reply.startsWith((parseInt(q.slice(0,2),16)+64).toString(16).toUpperCase()+q.slice(2)))throw Error('Chybná čtecí odpověď.');this.event('data',{values:this.ecu.decode(r,reply)});}
 if(step.type==='routine'){await this.fingerprint(s);await this.checks(s.preconditions);const r=this.ecu.requests.find(r=>r.name===step.request);this.event('intent',{request:hex(r.sentbytes)});if(this.storageError)throw Error('Nelze trvale uložit protokol: '+this.storageError);if(hex(r.sentbytes).startsWith('3101'))this.started=true;const response=await this.send(r.sentbytes);if(response!==hex(step.expect))throw Error('Výsledek rutiny neodpovídá očekávání: '+response);}
 if(step.type==='monitor'){const deadline=this.now()+step.timeoutMs;let reached=false;while(this.now()<deadline){this.abort();await this.keepAlive(s);await this.checks(s.preconditions);if(await this.evaluate(step.until)){reached=true;break;}await this.sleep(step.intervalMs);}if(!reached)throw Error('Vypršel čas sledování.');}}
 await this.checks(s.postconditions);completed=true;this.event('complete',{verified:true});return {status:'Ověřeno',events:this.events};
 }catch(e){this.event('error',{message:e.message});if(this.started&&s.stop){try{const r=this.ecu.requests.find(r=>r.name===s.stop.request);this.event('stop-intent',{request:hex(r.sentbytes)});if(await this.send(r.sentbytes)!==hex(s.stop.expect))throw Error('Nepotvrzené zastavení');this.event('stopped',{confirmed:true});}catch(stopError){uncertain=true;this.event('uncertain',{message:'Zastavení nebylo potvrzeno: '+stopError.message});}}
 return {status:uncertain?'Nejistý stav ECU – zastavení nepotvrzeno':this.started?'Přerušeno; zastavení potvrzeno':'Zastaveno před rutinou',error:e.message,events:this.events};
 }finally{if(s.session){try{const r=await this.send('1001');if(!r.startsWith('5001'))throw Error('Neshoda');this.event('session-closed',{});}catch(e){this.event('warning',{message:'Návrat do výchozí relace nepotvrzen.'});}}if(!completed)this.event('end',{verified:false});}
 }
}
